<?php
if(!isset($_SESSION['ID']) || !in_array($_SESSION['ROLE']??'', ['admin','mho'],true)){http_response_code(403);exit;}
$year=(int)($_GET['year']??date('Y'));if($year<2000 || $year>2100)$year=(int)date('Y');
$q=$pdo->prepare('SELECT MONTH(consultation_date) AS month_no, COUNT(*) AS total FROM consultations WHERE YEAR(consultation_date)=? GROUP BY MONTH(consultation_date)');$q->execute([$year]);$monthly=array_fill(1,12,0);foreach($q->fetchAll() as $r)$monthly[(int)$r['month_no']]=(int)$r['total'];
$total=(int)$pdo->query('SELECT COUNT(*) FROM residents')->fetchColumn();
$vaccinated=(int)$pdo->query("SELECT COUNT(DISTINCT resident_id) FROM vaccinations WHERE LOWER(TRIM(status))='completed'")->fetchColumn();$coverage=$total?round(100*$vaccinated/$total,1):null;
$q=$pdo->prepare("SELECT m.medicine_name,m.unit,SUM(t.quantity) AS total FROM medicine_transactions t JOIN medicines m ON m.medicine_id=t.medicine_id WHERE t.transaction_type='stock_out' AND m.category='Medicine' AND YEAR(t.transaction_date)=? GROUP BY m.medicine_name,m.unit ORDER BY m.medicine_name");$q->execute([$year]);$distribution=$q->fetchAll();
$maternal=[];foreach(['pregnancies','prenatal_visits','child_health','health_visits'] as $table)$maternal[$table]=(int)$pdo->query("SELECT COUNT(*) FROM $table")->fetchColumn();
?>
<section class="card p-3 mb-4"><h3 class="h5">Health Reports and Analytics</h3><form method="get" class="d-flex gap-2 mb-3"><label for="year">Report year</label><input class="form-control w-auto" id="year" name="year" type="number" min="2000" max="2100" value="<?= $year ?>"><button class="btn btn-primary">View</button></form>
<div class="row g-3 mb-3"><div class="col-md-4"><div class="card p-3">Registered residents<h3><?=$total?></h3></div></div><div class="col-md-4"><div class="card p-3">Consultations (<?=$year?>)<h3><?=array_sum($monthly)?></h3></div></div><div class="col-md-4"><div class="card p-3">Vaccination coverage<h3><?=$coverage===null?'N/A':$coverage.'%'?></h3><small><?=$vaccinated?> of <?=$total?> residents with at least one completed vaccination record (all time; not vaccine-specific coverage).</small></div></div></div>
<h4 class="h6">Monthly consultations (<?=$year?>)</h4><?php foreach($monthly as $m=>$n):?><div class="row align-items-center mb-2"><div class="col-2"><?=date('M',mktime(0,0,0,$m,1))?></div><div class="col-8"><div class="progress"><div class="progress-bar" style="background:#123B70;width:<?=100*$n/max(1,max($monthly))?>%"></div></div></div><div class="col-2"><?=$n?></div></div><?php endforeach;?>
<h4 class="h6 mt-4">Medicine distribution (<?=$year?>)</h4><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Medicine</th><th>Unit</th><th>Quantity distributed</th></tr></thead><tbody><?php foreach($distribution as $r):?><tr><td><?=htmlspecialchars($r['medicine_name'])?></td><td><?=htmlspecialchars($r['unit'])?></td><td><?=(int)$r['total']?></td></tr><?php endforeach;?><?php if(!$distribution):?><tr><td colspan="3">No distribution records for this year.</td></tr><?php endif;?></tbody></table></div>
<h4 class="h6">Maternal and child health (all time)</h4><div class="row g-2"><?php foreach($maternal as $k=>$n):?><div class="col-md-3"><div class="card p-2"><?=htmlspecialchars(ucwords(str_replace('_',' ',$k)))?><strong><?=$n?></strong></div></div><?php endforeach;?></div></section>
